INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(3112073, 437700, 16402, '<td valign="top">With such a great looking dog and expression I think I''d have cropped way in on his/her face. The background is pretty distracting and not really very flattering.</td>', 'With such a great looking dog and expression I think I''d have cropped way in on his/her face. The background is pretty distracting and not really very flattering.', '2006-12-13 08:00:53.000000', NULL, 1),
(3112076, 437019, 16402, '<td valign="top">This would have done better with me if it was larger.</td>', 'This would have done better with me if it was larger.', '2006-12-13 08:05:32.000000', NULL, 1),
(3112078, 436193, 16241, '<td valign="top">cute</td>', 'cute', '2006-12-13 08:06:50.000000', NULL, 1),
(3112079, 436014, 43463, '<td valign="top">What a sweet and adorable shot! This cute and cuddly kitten is all snuggled up with a candy cane. The picture truly does speak "Sweet Dreams"; you made an correct choice with the title. Two critiques on the shot. The whites of the kitten and the cane are an off white/cream white. A brighter white would really pop off that red - perhaps playing with color levels and/or brightness &amp; contrast would help the colors really pop off the page. Next an smaller aperature 8 and up alongside a long shutter speed will help with the depth of field. It will help capture all the lovely details you have now but it would have all of the candy cane in sharp focus. The part of the candy cane that is closest to us is slightly out of focus. Nonetheless this is a great portrait. 8</td>', 'What a sweet and adorable shot! This cute and cuddly kitten is all snuggled up with a candy cane. The picture truly does speak "Sweet Dreams"; you made an correct choice with the title. Two critiques on the shot. The whites of the kitten and the cane are an off white/cream white. A brighter white would really pop off that red - perhaps playing with color levels and/or brightness & contrast would help the colors really pop off the page. Next an smaller aperature 8 and up alongside a long shutter speed will help with the depth of field. It will help capture all the lovely details you have now but it would have all of the candy cane in sharp focus. The part of the candy cane that is closest to us is slightly out of focus. Nonetheless this is a great portrait. 8', '2006-12-13 08:07:17.000000', NULL, 1),
(3112081, 437814, 67152, '<td valign="top">love the face - love the background - nice job</td>', 'love the face - love the background - nice job', '2006-12-13 08:08:21.000000', NULL, 1),
(3112083, 437798, 16402, '<td valign="top">Not sure what that is coming out behind the right ear, but it''s distracting in an otherwise pretty darn nice shot.</td>', 'Not sure what that is coming out behind the right ear, but it''s distracting in an otherwise pretty darn nice shot.', '2006-12-13 08:08:46.000000', NULL, 1),
(3112085, 435912, 67152, '<td valign="top">love the face, the tongue, the nose - but the harsh flash and yellow eyes really take this down</td>', 'love the face, the tongue, the nose - but the harsh flash and yellow eyes really take this down', '2006-12-13 08:09:36.000000', NULL, 1),
(3112086, 437791, 58728, '<td valign="top">He''s (or she;s) SO cute!!!  I wish that the feet weren''t chopped off though.  :(</td>', 'He''s (or she;s) SO cute!!!  I wish that the feet weren''t chopped off though.  :(', '2006-12-13 08:09:37.000000', NULL, 1),
(3112087, 437613, 16402, '<td valign="top">Beautiful. Perrrrfect use of desaturation. 8</td>', 'Beautiful. Perrrrfect use of desaturation. 8', '2006-12-13 08:10:26.000000', NULL, 1),
