(3120006, 438011, 39850, '<td valign="top">5 - Quite ''human like'' capture/portrait, but the tongue dominates a bit too much in my opinion.</td>', '5 - Quite ''human like'' capture/portrait, but the tongue dominates a bit too much in my opinion.', '2006-12-15 07:57:37.000000', NULL, 1),
(3120007, 437494, 36397, '<td valign="top">Very red and a litte oversharpened, IMO, nice kat though.</td>', 'Very red and a litte oversharpened, IMO, nice kat though.', '2006-12-15 07:57:42.000000', NULL, 1),
