(3122638, 436233, 48360, '<td valign="top">Different perspective. I like it. Nice colors and clarity.</td>', 'Different perspective. I like it. Nice colors and clarity.', '2006-12-15 23:59:54.000000', NULL, 1),
(3122683, 437233, 50034, '<td valign="top">Powerful image!  Great job!  :)</td>', 'Powerful image!  Great job!  :)', '2006-12-16 00:32:43.000000', NULL, 1),
