(3123148, 437215, 64571, '<td valign="top">so cute</td>', 'so cute', '2006-12-16 08:47:50.000000', NULL, 1),
(3123151, 437580, 64571, '<td valign="top">really like this in b/w - good choice</td>', 'really like this in b/w - good choice', '2006-12-16 08:48:47.000000', NULL, 1),
(3123153, 435616, 64571, '<td valign="top">How adorable and the lighting is great!</td>', 'How adorable and the lighting is great!', '2006-12-16 08:49:13.000000', NULL, 1),
(3123154, 435716, 43565, '<td valign="top">This just does not work as a pet portrait for me.  I would like to see the eyes, and since the whole dog was included, his body.  I also prefer either a solid background or a setting that enhances the subject.  The pillow doesn''t do either IMO.</td>', 'This just does not work as a pet portrait for me.  I would like to see the eyes, and since the whole dog was included, his body.  I also prefer either a solid background or a setting that enhances the subject.  The pillow doesn''t do either IMO.', '2006-12-16 08:49:13.000000', NULL, 1),
(3123156, 437452, 43565, '<td valign="top">Chappy blends in too much with the background.  Perhaps different lighting or selective desat would help.</td>', 'Chappy blends in too much with the background.  Perhaps different lighting or selective desat would help.', '2006-12-16 08:49:19.000000', NULL, 1),
(3123158, 437601, 64571, '<td valign="top">Too cute!!!!!</td>', 'Too cute!!!!!', '2006-12-16 08:49:39.000000', NULL, 1),
(3123159, 436587, 64571, '<td valign="top">Great capture and detail.</td>', 'Great capture and detail.', '2006-12-16 08:49:51.000000', NULL, 1),
