INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(3131338, 437387, 46570, '<td valign="top">How precious. I personally prefer some bright colors...8</td>', 'How precious. I personally prefer some bright colors...8', '2006-12-19 12:03:38.000000', NULL, 1),
(3131345, 437743, 50034, '<td valign="top"><b>I know how it is!</b>  Some <i>"decorations"</i> choose their own spot on the Christmas tree without even asking!  <i>However, I''m sure we would all admit to preferring <b>FLASH</b> animation on the website called <b>LIFE!</b>  :)</i></td>', 'I know how it is!  Some "decorations" choose their own spot on the Christmas tree without even asking!  However, I''m sure we would all admit to preferring FLASH animation on the website called LIFE!  :)', '2006-12-19 12:06:56.000000', NULL, 1),
(3131350, 437851, 50034, '<td valign="top">"...And the next person who calls me, Liz, I think I''ll...I''ll...Well, I don''t know what I''ll do, but FYI the name''s ''Frank'' because I''m plain-spoken, not because of my shape!"  :}  Great Portrait!  Fine clarity!  Good Job!  :)</td>', '"...And the next person who calls me, Liz, I think I''ll...I''ll...Well, I don''t know what I''ll do, but FYI the name''s ''Frank'' because I''m plain-spoken, not because of my shape!"  :}  Great Portrait!  Fine clarity!  Good Job!  :)', '2006-12-19 12:11:42.000000', NULL, 1),
(3131359, 438053, 33535, '<td valign="top">this is the first half face cropped photo i see in this challenge and i love it.<br/>the overall black coloring, the down looking cat and her closed eyes imply a mysterious and sort of a sad feeling to the photo, which i really like.<br/>well done, it''s one of <i>my</i> favorites in this challenge. 10</td>', 'this is the first half face cropped photo i see in this challenge and i love it.the overall black coloring, the down looking cat and her closed eyes imply a mysterious and sort of a sad feeling to the photo, which i really like.well done, it''s one of my favorites in this challenge. 10', '2006-12-19 12:14:06.000000', NULL, 1),
(3131361, 437639, 50034, '<td valign="top">Sweet!  Confession is good for the soul, but some changes are easier said than done, Right?  Amazing Blue Eyes!  Great Portrait!  Fine clarity!  Good Job!  :)</td>', 'Sweet!  Confession is good for the soul, but some changes are easier said than done, Right?  Amazing Blue Eyes!  Great Portrait!  Fine clarity!  Good Job!  :)', '2006-12-19 12:14:29.000000', NULL, 1),
(3131364, 436233, 50034, '<td valign="top">Great Portrait!  Fine clarity!  Good Job!  :)</td>', 'Great Portrait!  Fine clarity!  Good Job!  :)', '2006-12-19 12:15:14.000000', NULL, 1),
